fullText:
* {
    margin: 0;
    padding: 0;
}

body {
    width: 95%;
    margin: auto;
    font-size: 17px;
}

header,footer {
    display: flex;
    justify-content: space-between;
    background: linear-gradient(to right, white, rgb(81, 161, 253));
}

img {
    width: 80px;
    height: 80px;
    border-radius: 50%;
}

h1 {
    margin: auto;
}

span {
    color: yellow;
}

main {
    background: url(files/4.jpg);
    background-repeat: no-repeat;
    background-size: cover;
    margin-top: 30px;
    margin-bottom: 30px;
}

nav {
    margin-left: 75%;
    font-family: Georgia, 'Times NewRoman', Times, serif;
    font-weight: bolder;
}

li {
    list-style: none;
    display: inline-block;
    padding: 3%;
}

nav ul li a {
    color: rgb(81, 161, 253);
}

form {
    margin-left: 40%;
    box-shadow: 10px 5px 5px 10px rgba(81, 161, 253, 0.8);
    border-radius: 20px 15px;
    width: 40%;
    height: 40%;
}

fieldset {
    border-top: 20px solid #333;
    border-bottom: 10px solid #333;
    border-left: none;
    border-right: none;
    background: transparent;
    justify-content: center;
}

legend {
    text-transform: capitalize;
    font-variant: small-caps;
    background: #fff;
    color: #333;
    margin-left: 35%;
    padding: 10px 20px;
    font-size: 24px;
    border-radius: 8px 8px 0 0;
    border-style: double;
}

.label {
    display: inline-block;
    padding: 10px;
    font-family: Georgia, 'TimeNew Roman', Times, serif;
    color: navy;
    border-bottom: navy double;
    text-align: center;
}

p {
    font-style: italic;
    font-weight: bolder;
}

.largeur {
    width: 150px;
}

.largeur1 {
    width: 200px;
    height: 30px;
}

input,select,textarea {
    margin: 20px;
    padding: 5px;
    border-radius: 8px;
    border: 2px solid rgb(66, 66, 82);
}

.center {
    text-align: center;
}

.ft {
    height: 60px;
    width: 60px;
}

.ft2 {
    height: 30px;
    width: 30px;
}

#div {
    Width: 90px;
}

#label {
    display: inline-block;
    font-family: Georgia, 'TimesNew Roman', Times, serif;
    color: navy;
    margin: auto;
}

#fb:hover {
    scale: 1.5;
}

#yt:hover {
    scale: 1.5;
}

#tt:hover {
    scale: 1.5;
}

#ins:hover {
    scale: 1.5;
}

